function pattern (str, type) {
  const types = {
    pub: /^\d\d\d/, // publication
    tes: /^t\d\d\d/,
    members: /^m\d\d\d/
  }
  if (type in types) {
    return types[type].test(str)
  } else if (type === 'infra') {
    for (const t in types) {
      if (types[t].test(str)) {
        return false
      }
    }
    return true
  }
  return false
}

window.ppp = pattern

